import{_ as a,c as i,o as e,a5 as s}from"./chunks/framework.DorIfSpC.js";const b=JSON.parse('{"title":"Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/ai/embedding-atlas-intro"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/ai/embedding-atlas-intro"}],["meta",{"property":"og:title","content":"Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖 | 星智未來"}],["meta",{"name":"twitter:title","content":"Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/ai/embedding-atlas-intro\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/ai/embedding-atlas-intro\\"}}"]]},"headers":[],"relativePath":"ai/embedding-atlas-intro.md","filePath":"ai/embedding-atlas-intro.md","lastUpdated":1778739462000}'),l={name:"ai/embedding-atlas-intro.md"};function n(r,t,d,o,h,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="embedding-atlas-讓-ai-幫你把大量文字變成一張藏寶圖" tabindex="-1">Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖 <a class="header-anchor" href="#embedding-atlas-讓-ai-幫你把大量文字變成一張藏寶圖" aria-label="Permalink to &quot;Embedding Atlas：讓 AI 幫你把大量文字變成一張藏寶圖&quot;">​</a></h1><blockquote><p>🔗 GitHub：<a href="https://github.com/apple/embedding-atlas" target="_blank" rel="noreferrer">https://github.com/apple/embedding-atlas</a></p><p>🎮 線上 Demo：<a href="https://apple.github.io/embedding-atlas" target="_blank" rel="noreferrer">https://apple.github.io/embedding-atlas</a></p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 11 月</p><hr><h2 id="前言-大量文字資料的困境" tabindex="-1">前言：大量文字資料的困境 <a class="header-anchor" href="#前言-大量文字資料的困境" aria-label="Permalink to &quot;前言：大量文字資料的困境&quot;">​</a></h2><p>你是否遇過這些情況？</p><ul><li>行銷部門收到上千則客戶回饋，不知從何看起</li><li>HR 要分析員工滿意度調查的開放式回答，只能一則一則讀</li><li>客服主管想知道客訴的主要類型，但資料太多無法人工分類</li></ul><p>傳統做法不外乎：人工標籤、關鍵字搜尋、或者做成文字雲。但這些方法不是太慢，就是太粗糙，很難真正「看懂」資料的全貌。</p><p>Apple 最近開源了一個工具——<strong>Embedding Atlas</strong>，正好能解決這個問題。</p><hr><h2 id="什麼是-embedding-atlas" tabindex="-1">什麼是 Embedding Atlas？ <a class="header-anchor" href="#什麼是-embedding-atlas" aria-label="Permalink to &quot;什麼是 Embedding Atlas？&quot;">​</a></h2><p>簡單說，它是一個<strong>把大量文字自動變成互動地圖</strong>的工具。</p><p>運作原理是這樣的：</p><ol><li><strong>把文字變成數字</strong>：AI 會把每段文字轉換成一組「嵌入向量」（你可以想像成文字的 GPS 座標）</li><li><strong>相似的聚在一起</strong>：意思相近的文字，座標會很接近</li><li><strong>降維成 2D 地圖</strong>：透過演算法把高維資料壓縮成平面，讓人眼可以看</li><li><strong>自動分群與標籤</strong>：工具會自動把相似的資料圈成一群，並嘗試命名</li></ol><p>最後你看到的，就是一張可以放大、縮小、點擊、篩選的<strong>互動式資料地圖</strong>。</p><hr><h2 id="核心功能一覽" tabindex="-1">核心功能一覽 <a class="header-anchor" href="#核心功能一覽" aria-label="Permalink to &quot;核心功能一覽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>說明</th></tr></thead><tbody><tr><td>🏷️ 自動聚類與標籤</td><td>不用人工分類，AI 自動把相似資料分群</td></tr><tr><td>🫧 密度視覺化</td><td>一眼看出哪裡資料最密集、哪裡是離群值</td></tr><tr><td>🔍 即時搜尋</td><td>輸入關鍵字，立刻找到相關資料點</td></tr><tr><td>📊 多欄位篩選</td><td>結合其他欄位（日期、類別）交叉分析</td></tr><tr><td>🚀 高效能</td><td>支援到幾百萬筆資料，瀏覽器內流暢運行</td></tr><tr><td>🔒 資料隱私</td><td>完全本機運算，資料不會上傳到任何地方</td></tr></tbody></table><hr><h2 id="辦公室應用場景" tabindex="-1">辦公室應用場景 <a class="header-anchor" href="#辦公室應用場景" aria-label="Permalink to &quot;辦公室應用場景&quot;">​</a></h2><h3 id="📢-行銷部門" tabindex="-1">📢 行銷部門 <a class="header-anchor" href="#📢-行銷部門" aria-label="Permalink to &quot;📢 行銷部門&quot;">​</a></h3><p><strong>應用：客戶回饋與市場聲量分析</strong></p><p>把客戶問卷的開放題、社群評論、產品 Review 匯入工具，30 秒後就能看到：</p><ul><li>客戶主要在討論哪些主題</li><li>正面 vs 負面評價的分佈</li><li>競品討論集中在哪些面向</li></ul><p><strong>效益</strong>：從「一則一則讀」變成「一眼看全貌」，分析時間從數天縮短到數小時。</p><hr><h3 id="👥-人力資源部門" tabindex="-1">👥 人力資源部門 <a class="header-anchor" href="#👥-人力資源部門" aria-label="Permalink to &quot;👥 人力資源部門&quot;">​</a></h3><p><strong>應用 1：員工滿意度調查分析</strong></p><p>員工填寫的開放式回答，往往藏著最真實的心聲。把這些回答視覺化後，可以清楚看到：</p><ul><li>員工抱怨集中在哪幾個主題（薪資？主管？工作量？）</li><li>不同部門的回饋有什麼差異</li><li>哪些是個案、哪些是普遍現象</li></ul><p><strong>應用 2：離職面談紀錄探勘</strong></p><p>累積多年的離職面談紀錄，用這工具一次視覺化，找出離職原因的長期趨勢。</p><hr><h3 id="📞-客服部門" tabindex="-1">📞 客服部門 <a class="header-anchor" href="#📞-客服部門" aria-label="Permalink to &quot;📞 客服部門&quot;">​</a></h3><p><strong>應用：客訴分類與異常偵測</strong></p><p>把客服紀錄、客訴信件匯入後：</p><ul><li>自動看出客訴的主要類型與比例</li><li>發現新興的問題類型（地圖上出現新的群集）</li><li>找出離群的特殊案例，優先處理</li></ul><hr><h3 id="📚-知識管理" tabindex="-1">📚 知識管理 <a class="header-anchor" href="#📚-知識管理" aria-label="Permalink to &quot;📚 知識管理&quot;">​</a></h3><p><strong>應用：內部文件盤點</strong></p><p>公司累積大量 SOP、技術文件、會議紀錄，用這工具可以：</p><ul><li>看出哪些主題文件最多、哪些缺乏</li><li>找出內容重複的文件</li><li>發現「孤島知識」——沒被其他文件參照的內容</li></ul><hr><h2 id="怎麼開始使用" tabindex="-1">怎麼開始使用？ <a class="header-anchor" href="#怎麼開始使用" aria-label="Permalink to &quot;怎麼開始使用？&quot;">​</a></h2><h3 id="最簡單的方式-命令列一行搞定" tabindex="-1">最簡單的方式：命令列一行搞定 <a class="header-anchor" href="#最簡單的方式-命令列一行搞定" aria-label="Permalink to &quot;最簡單的方式：命令列一行搞定&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 uv 執行（不需預先安裝）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> embedding-atlas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your_data.csv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --text</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;要分析的欄位名稱&quot;</span></span></code></pre></div><p>執行後打開 <code>http://localhost:5055/</code>，就能看到互動介面。</p><h3 id="在-jupyter-notebook-中使用" tabindex="-1">在 Jupyter Notebook 中使用 <a class="header-anchor" href="#在-jupyter-notebook-中使用" aria-label="Permalink to &quot;在 Jupyter Notebook 中使用&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> embedding_atlas </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmbeddingAtlas</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pandas </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">df </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pd.read_csv(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customer_feedback.csv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EmbeddingAtlas(df, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;feedback_content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="資料準備" tabindex="-1">資料準備 <a class="header-anchor" href="#資料準備" aria-label="Permalink to &quot;資料準備&quot;">​</a></h3><p>只需要準備一個 CSV 檔，包含：</p><ul><li>一個<strong>文字欄位</strong>（你想分析的內容）</li><li>其他欄位（日期、類別等）可用於篩選</li></ul><p><strong>不需要</strong>向量資料庫，<strong>不需要</strong>複雜的 ETL，工具會自動處理嵌入向量的計算。</p><hr><h2 id="跟其他工具的差異" tabindex="-1">跟其他工具的差異 <a class="header-anchor" href="#跟其他工具的差異" aria-label="Permalink to &quot;跟其他工具的差異&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Embedding Atlas</th><th>傳統文字雲</th><th>向量資料庫</th></tr></thead><tbody><tr><td>能看出語意關係</td><td>✅</td><td>❌</td><td>❌（要另外視覺化）</td></tr><tr><td>互動探索</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>上手難度</td><td>低</td><td>低</td><td>高</td></tr><tr><td>適合場景</td><td>探索、分析</td><td>簡報展示</td><td>生產環境檢索</td></tr></tbody></table><hr><h2 id="技術細節-給工程師" tabindex="-1">技術細節（給工程師） <a class="header-anchor" href="#技術細節-給工程師" aria-label="Permalink to &quot;技術細節（給工程師）&quot;">​</a></h2><ul><li><strong>嵌入模型</strong>：預設使用 <code>all-MiniLM-L6-v2</code>（文字）或 <code>ViT</code>（圖片），可自訂</li><li><strong>降維演算法</strong>：UMAP（WebAssembly 實作）</li><li><strong>前端渲染</strong>：WebGPU（支援 WebGL 2 fallback）</li><li><strong>資料庫</strong>：DuckDB（跑在瀏覽器的輕量資料庫）</li><li><strong>整合方式</strong>：支援 React、Svelte 元件嵌入</li></ul><p>如果已經有自己計算好的嵌入向量，可以直接傳入 x、y 座標：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">embedding-atlas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.csv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projection_x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projection_y</span></span></code></pre></div><hr><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>Embedding Atlas 降低了「理解大量文字資料」的門檻。以前需要資料科學家才能做的嵌入向量分析，現在行銷、HR、客服主管都能自己探索。</p><p>它不是要取代深度分析，而是讓你在<strong>動手分析之前，先看懂資料的全貌</strong>。</p><p>當你下次面對幾千則客戶回饋、員工意見、或客訴紀錄時，不妨試試這個工具。30 秒後，你會對資料有完全不同的理解。</p><hr><blockquote><p>📎 相關資源</p><ul><li>GitHub：<a href="https://github.com/apple/embedding-atlas" target="_blank" rel="noreferrer">apple/embedding-atlas</a></li><li>官方文件：<a href="https://apple.github.io/embedding-atlas/overview.html" target="_blank" rel="noreferrer">https://apple.github.io/embedding-atlas/overview.html</a></li><li>論文：<a href="https://arxiv.org/abs/2505.06386" target="_blank" rel="noreferrer">Embedding Atlas: Low-Friction, Interactive Embedding Visualization</a></li></ul></blockquote>`,68)])])}const k=a(l,[["render",n]]);export{b as __pageData,k as default};
